        status = 'VALIDATION_FAILED',
        message = v_validation_error
    WHERE
        cleanup_id = '44894cd7-88ec-4677-8975-d10fcc13275f'
        AND charge_id = 598020;
   
    RETURN;
END IF;

END IF;

