    '44894cd7-88ec-4677-8975-d10fcc13275f',
    'INSERT',
    'AFTER'
FROM JISJDW.CJIS_DOCKET source_row
WHERE CJIS_DOCKET_ID = v_inserted_id;


JISREM.LOG
(
    p_cleanup_id    => '44894cd7-88ec-4677-8975-d10fcc13275f',
    p_charge_id       => '598020',
    p_step_name     => 'InsertCleanupDocketEntry__INSERT',
    p_affected_rows => v_count
);

JISREM.LOG
(
    p_cleanup_id => '44894cd7-88ec-4677-8975-d10fcc13275f',
    p_charge_id    => '598020',
    p_step_name  => 'CLEANUP',
    p_message    => 'Completed cleanup for case'
);

        UPDATE
            JISREM.CLEANUP_CASE_QUEUE
        SET
            status = 'PROCESSED'
        WHERE
            cleanup_id = '44894cd7-88ec-4677-8975-d10fcc13275f'
            AND charge_id = '598020';

   IF 0 = 0 THEN
        COMMIT;
    ELSE
        ROLLBACK;
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        v_error_message := SUBSTR(SQLERRM, 1, 512);

        ROLLBACK;
        
        JISREM.LOG
        (
            p_cleanup_id => '44894cd7-88ec-4677-8975-d10fcc13275f',
            p_charge_id    => '598020',
            p_step_name  => 'EXCEPTION',
            p_message    => v_error_message
        );
        
        UPDATE JISREM.CLEANUP_CASE_QUEUE
        SET 
            status = 'PROCESSING_FAILED',
            message = v_error_message
        WHERE cleanup_id = '44894cd7-88ec-4677-8975-d10fcc13275f'
        AND charge_id = '598020';
        
END;
/

BEGIN
 IF 0 = 0 THEN
    UPDATE JISREM.CLEANUP 
    SET 
        status='CHARGES_PROCESSED'
    WHERE cleanup_id = '44894cd7-88ec-4677-8975-d10fcc13275f';
    
    JISREM.LOG
    (
        p_cleanup_id => '44894cd7-88ec-4677-8975-d10fcc13275f',
        p_step_name  => 'TRANSACTION',
        p_message    => 'All charges processed'
    );
    
 ELSE
    JISREM.LOG
    (
        p_cleanup_id => '44894cd7-88ec-4677-8975-d10fcc13275f',
        p_step_name  => 'TRANSACTION',
        p_message    => 'WHAT-IF was true all charges rolled back'
    );
 END IF;
END;
/

